contracts/staking/LexaStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title LexaStaking
 * @dev Staking contract for LEXA tokens with multiple tiers and maturity-based rewards
 * @notice Features: Tiered staking, reward reservation, referral bonuses, emergency pause
 */
contract LexaStaking is ReentrancyGuard, Ownable, Pausable {
    using SafeERC20 for IERC20;

    // ==================== ENUMS ====================
    enum StakingTier {
        BRONZE,
        SILVER,
        GOLD
    }

    // ==================== STRUCTS ====================
    /// @dev Configuration for each staking tier
    struct TierConfig {
        uint256 minStakeAmount; // Minimum stake in LEXA tokens (e.g., 10e18 for 10 LEXA)
        uint256 roi90days; // ROI percentage for 90-day lock (e.g., 5 = 5%)
        uint256 roi180days; // ROI percentage for 180-day lock
    }

    /// @dev User's staking position
    struct UserStake {
        uint256 amount; // Principal amount staked
        uint256 lockDurationDays; // Lock duration (90 or 180)
        uint256 startTimestamp; // When the stake was initiated
        StakingTier tier; // Which tier was selected
        uint256 totalRewardsEntitled; // Total rewards based on ROI (reserved at stake time)
        uint256 totalRewardsClaimed; // Amount of rewards already claimed
        bool active; // Whether this stake is still active
    }

    // ==================== STATE VARIABLES ====================
    IERC20 public lexaToken;
    
    // Tier configurations
    TierConfig[3] public tiers;
    
    // User stakes: user address => stake index => UserStake
    mapping(address user => mapping(uint256 index => UserStake)) public userStakes;
    /// @dev Track how many stakes each user has
    mapping(address user => uint256) public userStakeCount;
    
    // Referral tracking
    mapping(address referrer => uint256) public referralRewardsClaimed;
    mapping(address staker => address referrer) public stakerReferrer;
    /// @dev Track if a staker has already used a referrer to prevent duplicate bonuses
    mapping(address staker => bool) public hasUsedReferrer;
    
    // Admin settings
    uint256 public referralRewardAmount = 50e18; // 50 LEXA per successful referral
    uint256 public rewardPoolBalance; // Unreserved rewards available for new stakes/referrals
    uint256 public reservedRewardBalance; // Rewards reserved for existing active stakes
    uint256 public totalLockedPrincipal; // Active user principal locked in the contract
    
    // Pausable staking
    bool public stakingPaused = false;
    
    // Constants
    uint256 private constant SECONDS_PER_DAY = 86400;
    uint256 private constant PRECISION = 100; // For percentage calculations (5 = 5%)

    // ==================== EVENTS ====================
    event Staked(
        address indexed user,
        StakingTier tier,
        uint256 amount,
        uint256 lockDurationDays,
        uint256 totalRewardsEntitled,
        address indexed referrer,
        uint256 timestamp
    );

    event RewardsClaimed(
        address indexed user,
        uint256 stakeIndex,
        uint256 rewardsAmount,
        uint256 timestamp
    );

    event RewardsRestaked(
        address indexed user,
        uint256 stakeIndex,
        uint256 rewardAmount,
        uint256 timestamp
    );

    event Unstaked(
        address indexed user,
        uint256 stakeIndex,
        uint256 principalAmount,
        uint256 unclaimedRewards,
        uint256 timestamp
    );

    event ReferralRewarded(
        address indexed referrer,
        address indexed newStaker,
        uint256 rewardAmount,
        uint256 timestamp
    );

    event RewardPoolFunded(
        address indexed funder,
        uint256 amount,
        uint256 timestamp
    );

    event ReferralRewardAmountUpdated(
        uint256 newAmount,
        uint256 timestamp
    );

    event StakingPausedToggled(
        bool isPaused,
        uint256 timestamp
    );

    event EmergencyTokenRecovery(
        address indexed token,
        uint256 amount,
        address indexed recipient,
        uint256 timestamp
    );

    // ==================== MODIFIERS ====================
    modifier stakingEnabled() {
        require(!stakingPaused && !paused(), "Staking is currently paused");
        _;
    }

    modifier validTier(StakingTier _tier) {
        require(uint8(_tier) < 3, "Invalid tier");
        _;
    }

    modifier validDuration(uint256 _durationDays) {
        require(_durationDays == 90 || _durationDays == 180, "Duration must be 90 or 180 days");
        _;
    }

    // ==================== CONSTRUCTOR ====================
    constructor(address _lexaToken) Ownable(msg.sender) Pausable() {
        require(_lexaToken != address(0), "Invalid token address");
        lexaToken = IERC20(_lexaToken);

        // Initialize tier configurations
        // Bronze: 10 LEXA min, 5% (90d), 10% (180d)
        tiers[uint8(StakingTier.BRONZE)] = TierConfig({
            minStakeAmount: 10e18,
            roi90days: 5,
            roi180days: 10
        });

        // Silver: 20 LEXA min, 10% (90d), 25% (180d)
        tiers[uint8(StakingTier.SILVER)] = TierConfig({
            minStakeAmount: 20e18,
            roi90days: 10,
            roi180days: 25
        });

        // Gold: 50 LEXA min, 15% (90d), 35% (180d)
        tiers[uint8(StakingTier.GOLD)] = TierConfig({
            minStakeAmount: 50e18,
            roi90days: 15,
            roi180days: 35
        });
    }

    // ==================== CORE STAKING FUNCTIONS ====================

    /**
     * @notice Stake LEXA tokens with optional referral
     * @param _amount Amount of LEXA to stake
     * @param _tier Staking tier (0=Bronze, 1=Silver, 2=Gold)
     * @param _durationDays Lock duration (90 or 180 days)
     * @param _referrer Address of referrer (use address(0) for no referrer)
     */
    function stake(
        uint256 _amount,
        StakingTier _tier,
        uint256 _durationDays,
        address _referrer
    ) 
        external 
        nonReentrant 
        stakingEnabled 
        validTier(_tier) 
        validDuration(_durationDays)
    {
        require(_amount > 0, "Stake amount must be greater than zero");
        require(_referrer != msg.sender, "Cannot self-refer");

        // Transfer tokens from user to contract and account for fee-on-transfer tokens.
        uint256 balanceBefore = lexaToken.balanceOf(address(this));
        lexaToken.safeTransferFrom(msg.sender, address(this), _amount);
        uint256 receivedAmount = lexaToken.balanceOf(address(this)) - balanceBefore;
        require(receivedAmount > 0, "No tokens received");

        require(
            receivedAmount >= tiers[uint8(_tier)].minStakeAmount,
            "Amount below minimum for tier"
        );

        // Calculate and reserve rewards based on ROI. Rewards are backed up-front.
        uint256 totalRewardsEntitled = _calculateReward(
            receivedAmount,
            _tier,
            _durationDays
        );

        bool shouldRewardReferrer = _referrer != address(0) && !hasUsedReferrer[msg.sender];
        uint256 requiredRewardFunding = totalRewardsEntitled + (
            shouldRewardReferrer ? referralRewardAmount : 0
        );
        require(
            rewardPoolBalance >= requiredRewardFunding,
            "Insufficient reward pool"
        );

        rewardPoolBalance -= totalRewardsEntitled;
        reservedRewardBalance += totalRewardsEntitled;
        totalLockedPrincipal += receivedAmount;

        // Create stake
        uint256 stakeIndex = userStakeCount[msg.sender];
        userStakes[msg.sender][stakeIndex] = UserStake({
            amount: receivedAmount,
            lockDurationDays: _durationDays,
            startTimestamp: block.timestamp,
            tier: _tier,
            totalRewardsEntitled: totalRewardsEntitled,
            totalRewardsClaimed: 0,
            active: true
        });
        userStakeCount[msg.sender]++;

        // Handle referral if provided
        if (shouldRewardReferrer) {
            hasUsedReferrer[msg.sender] = true;
            stakerReferrer[msg.sender] = _referrer;

            // Distribute referral reward
            rewardPoolBalance -= referralRewardAmount;
            lexaToken.safeTransfer(_referrer, referralRewardAmount);
            referralRewardsClaimed[_referrer] += referralRewardAmount;

            emit ReferralRewarded(
                _referrer,
                msg.sender,
                referralRewardAmount,
                block.timestamp
            );
        }

        emit Staked(
            msg.sender,
            _tier,
            receivedAmount,
            _durationDays,
            totalRewardsEntitled,
            _referrer,
            block.timestamp
        );
    }

    // ==================== REWARD FUNCTIONS ====================

    /**
     * @notice Calculate claimable rewards for a specific stake
     * @param _user User address
     * @param _stakeIndex Index of the stake
     * @return Claimable rewards amount, zero until the stake matures
     */
    function getAccumulatedRewards(address _user, uint256 _stakeIndex) 
        public 
        view 
        returns (uint256) 
    {
        require(_stakeIndex < userStakeCount[_user], "Invalid stake index");
        
        UserStake memory stakeData = userStakes[_user][_stakeIndex];
        require(stakeData.active, "Stake is not active");

        uint256 lockDurationSeconds = stakeData.lockDurationDays * SECONDS_PER_DAY;
        uint256 elapsedTime = block.timestamp - stakeData.startTimestamp;

        if (elapsedTime < lockDurationSeconds) {
            return 0;
        }

        uint256 pending = stakeData.totalRewardsEntitled > stakeData.totalRewardsClaimed 
            ? stakeData.totalRewardsEntitled - stakeData.totalRewardsClaimed 
            : 0;

        return pending;
    }

    /**
     * @notice Check if a stake has matured
     * @param _user User address
     * @param _stakeIndex Index of the stake
     * @return true if lock period has expired
     */
    function isStakeMatured(address _user, uint256 _stakeIndex) 
        public 
        view 
        returns (bool) 
    {
        require(_stakeIndex < userStakeCount[_user], "Invalid stake index");
        
        UserStake memory stakeData = userStakes[_user][_stakeIndex];
        uint256 lockDurationSeconds = stakeData.lockDurationDays * SECONDS_PER_DAY;
        return (block.timestamp - stakeData.startTimestamp) >= lockDurationSeconds;
    }

    /**
     * @notice Claim rewards after maturity without unstaking
     * @param _stakeIndex Index of the stake
     */
    function claimRewards(uint256 _stakeIndex) 
        external 
        nonReentrant 
    {
        require(_stakeIndex < userStakeCount[msg.sender], "Invalid stake index");
        
        UserStake storage stakeData = userStakes[msg.sender][_stakeIndex];
        require(stakeData.active, "Stake is not active");
        require(isStakeMatured(msg.sender, _stakeIndex), "Stake is still locked");

        uint256 pendingRewards = getAccumulatedRewards(msg.sender, _stakeIndex);
        require(pendingRewards > 0, "No rewards to claim");

        // Check that reserved rewards are backed without touching user principal.
        require(reservedRewardBalance >= pendingRewards, "Insufficient reserved rewards");
        require(
            _availableRewardTokens() >= pendingRewards,
            "Insufficient reward backing"
        );

        // Update claimed rewards
        stakeData.totalRewardsClaimed += pendingRewards;
        reservedRewardBalance -= pendingRewards;

        // Transfer rewards
        lexaToken.safeTransfer(msg.sender, pendingRewards);

        emit RewardsClaimed(msg.sender, _stakeIndex, pendingRewards, block.timestamp);
    }

    /**
     * @notice Restake rewards back into the same stake position (extends lock period)
     * @param _stakeIndex Index of the stake
     */
    function restakeRewards(uint256 _stakeIndex) 
        external 
        nonReentrant 
    {
        require(_stakeIndex < userStakeCount[msg.sender], "Invalid stake index");
        
        UserStake storage stakeData = userStakes[msg.sender][_stakeIndex];
        require(stakeData.active, "Stake is not active");
        require(isStakeMatured(msg.sender, _stakeIndex), "Stake is still locked");

        uint256 pendingRewards = getAccumulatedRewards(msg.sender, _stakeIndex);
        require(pendingRewards > 0, "No rewards to restake");
        require(reservedRewardBalance >= pendingRewards, "Insufficient reserved rewards");
        require(
            _availableRewardTokens() >= pendingRewards,
            "Insufficient reward backing"
        );

        uint256 newPrincipal = stakeData.amount + pendingRewards;
        uint256 roiPercentage = stakeData.lockDurationDays == 90
            ? tiers[uint8(stakeData.tier)].roi90days
            : tiers[uint8(stakeData.tier)].roi180days;
        uint256 newRewardsEntitled = (newPrincipal * roiPercentage) / PRECISION;
        require(rewardPoolBalance >= newRewardsEntitled, "Insufficient reward pool");

        // Convert matured rewards into principal and begin a new lock cycle.
        reservedRewardBalance = reservedRewardBalance - pendingRewards + newRewardsEntitled;
        rewardPoolBalance -= newRewardsEntitled;
        totalLockedPrincipal += pendingRewards;

        stakeData.amount = newPrincipal;
        stakeData.startTimestamp = block.timestamp;
        stakeData.totalRewardsEntitled = newRewardsEntitled;
        stakeData.totalRewardsClaimed = 0;

        emit RewardsRestaked(msg.sender, _stakeIndex, pendingRewards, block.timestamp);
    }

    // ==================== UNSTAKING FUNCTIONS ====================

    /**
     * @notice Unstake after maturity, claiming all remaining rewards
     * @param _stakeIndex Index of the stake
     */
    function unstake(uint256 _stakeIndex) 
        external 
        nonReentrant 
    {
        require(_stakeIndex < userStakeCount[msg.sender], "Invalid stake index");
        
        UserStake storage stakeData = userStakes[msg.sender][_stakeIndex];
        require(stakeData.active, "Stake is not active");
        require(isStakeMatured(msg.sender, _stakeIndex), "Stake is still locked");

        uint256 unclaimedRewards = getAccumulatedRewards(msg.sender, _stakeIndex);
        uint256 principalAmount = stakeData.amount;

        // Calculate total to return
        uint256 totalReturn = principalAmount + unclaimedRewards;

        require(reservedRewardBalance >= unclaimedRewards, "Insufficient reserved rewards");
        require(
            _availableRewardTokens() >= unclaimedRewards,
            "Insufficient reward backing"
        );
        uint256 contractBalance = lexaToken.balanceOf(address(this));
        require(
            contractBalance >= totalReturn,
            "Insufficient contract balance for unstaking"
        );

        // Mark stake as inactive and release accounting reservations.
        stakeData.active = false;
        stakeData.totalRewardsClaimed += unclaimedRewards;
        totalLockedPrincipal -= principalAmount;
        reservedRewardBalance -= unclaimedRewards;

        // Transfer principal + unclaimed rewards back to user
        lexaToken.safeTransfer(msg.sender, totalReturn);

        emit Unstaked(
            msg.sender,
            _stakeIndex,
            principalAmount,
            unclaimedRewards,
            block.timestamp
        );
    }

    // ==================== ADMIN FUNCTIONS ====================

    /**
     * @notice Fund the reward pool
     * @param _amount Amount of LEXA to add to pool
     */
    function fundRewardPool(uint256 _amount) 
        external 
        onlyOwner 
    {
        require(_amount > 0, "Amount must be greater than zero");
        uint256 balanceBefore = lexaToken.balanceOf(address(this));
        lexaToken.safeTransferFrom(msg.sender, address(this), _amount);
        uint256 receivedAmount = lexaToken.balanceOf(address(this)) - balanceBefore;
        require(receivedAmount > 0, "No tokens received");
        rewardPoolBalance += receivedAmount;

        emit RewardPoolFunded(msg.sender, receivedAmount, block.timestamp);
    }

    /**
     * @notice Update referral reward amount
     * @param _newAmount New referral reward in LEXA (e.g., 50e18 for 50 LEXA)
     */
    function setReferralRewardAmount(uint256 _newAmount) 
        external 
        onlyOwner 
    {
        require(_newAmount > 0, "Amount must be greater than zero");
        referralRewardAmount = _newAmount;

        emit ReferralRewardAmountUpdated(_newAmount, block.timestamp);
    }

    /**
     * @notice Pause/unpause staking
     * @param _isPaused true to pause, false to unpause
     */
    function setStakingPaused(bool _isPaused) 
        external 
        onlyOwner 
    {
        stakingPaused = _isPaused;
        emit StakingPausedToggled(_isPaused, block.timestamp);
    }

    /**
     * @notice Emergency pause all contract operations
     */
    function pause() 
        external 
        onlyOwner 
    {
        _pause();
    }

    /**
     * @notice Unpause contract operations
     */
    function unpause() 
        external 
        onlyOwner 
    {
        _unpause();
    }

    /**
     * @notice Emergency recovery of unclaimed reward pool tokens
     * @notice IMPORTANT: Cannot withdraw locked user funds or reserved rewards
     */
    function emergencyRecoverTokens(uint256 _amount) 
        external 
        onlyOwner 
    {
        require(_amount > 0, "Amount must be greater than zero");
        require(_amount <= rewardPoolBalance, "Cannot exceed available recovery amount");
        require(_availableUnreservedRewardTokens() >= _amount, "Insufficient reward backing");

        rewardPoolBalance -= _amount;
        lexaToken.safeTransfer(owner(), _amount);

        emit EmergencyTokenRecovery(address(lexaToken), _amount, owner(), block.timestamp);
    }

    /**
     * @notice Withdraw excess LEXA tokens from the contract
     * @notice IMPORTANT: Can only withdraw amounts above what's locked in user stakes
     * @param _amount Amount of LEXA to withdraw
     */
    function withdrawExcessTokens(uint256 _amount) 
        external 
        onlyOwner 
    {
        require(_amount > 0, "Amount must be greater than zero");
        uint256 availableForWithdrawal = getUnaccountedTokenBalance();

        require(
            _amount <= availableForWithdrawal, 
            "Insufficient excess tokens"
        );
        
        // Transfer to owner
        lexaToken.safeTransfer(owner(), _amount);

        emit EmergencyTokenRecovery(address(lexaToken), _amount, owner(), block.timestamp);
    }

    /**
     * @notice Update tier configuration (careful with existing stakes!)
     * @param _tier Tier to update
     * @param _minStake New minimum stake
     * @param _roi90d New 90-day ROI percentage
     * @param _roi180d New 180-day ROI percentage
     */
    function updateTierConfig(
        StakingTier _tier,
        uint256 _minStake,
        uint256 _roi90d,
        uint256 _roi180d
    ) 
        external 
        onlyOwner 
        validTier(_tier) 
    {
        require(_minStake > 0, "Min stake must be greater than zero");
        require(_roi90d > 0 && _roi180d > 0, "ROI must be greater than zero");
        
        tiers[uint8(_tier)] = TierConfig({
            minStakeAmount: _minStake,
            roi90days: _roi90d,
            roi180days: _roi180d
        });
    }

    // ==================== VIEW FUNCTIONS ====================

    /**
     * @notice Get all stakes for a user
     * @param _user User address
     * @return Array of user stakes
     */
    function getUserStakes(address _user) 
        external 
        view 
        returns (UserStake[] memory) 
    {
        UserStake[] memory stakes = new UserStake[](userStakeCount[_user]);
        for (uint256 i = 0; i < userStakeCount[_user]; i++) {
            stakes[i] = userStakes[_user][i];
        }
        return stakes;
    }

    /**
     * @notice Get active stakes for a user
     * @param _user User address
     * @return Count of active stakes
     */
    function getActiveStakeCount(address _user) 
        external 
        view 
        returns (uint256) 
    {
        uint256 count = 0;
        for (uint256 i = 0; i < userStakeCount[_user]; i++) {
            if (userStakes[_user][i].active) {
                count++;
            }
        }
        return count;
    }

    /**
     * @notice Get tier configuration
     * @param _tier The tier to retrieve
     */
    function getTierConfig(StakingTier _tier) 
        external 
        view 
        validTier(_tier) 
        returns (TierConfig memory) 
    {
        return tiers[uint8(_tier)];
    }

    function _calculateReward(
        uint256 _amount,
        StakingTier _tier,
        uint256 _durationDays
    )
        internal
        view
        returns (uint256)
    {
        TierConfig memory tierConfig = tiers[uint8(_tier)];
        uint256 roiPercentage = _durationDays == 90
            ? tierConfig.roi90days
            : tierConfig.roi180days;

        return (_amount * roiPercentage) / PRECISION;
    }

    /**
     * @notice Get tokens in the contract that are not needed for active principal.
     * @dev Includes reserved rewards, unreserved reward pool tokens, and accidental transfers.
     */
    function _availableRewardTokens()
        internal
        view
        returns (uint256)
    {
        uint256 contractBalance = lexaToken.balanceOf(address(this));
        if (contractBalance <= totalLockedPrincipal) {
            return 0;
        }
        return contractBalance - totalLockedPrincipal;
    }

    function _availableUnreservedRewardTokens()
        internal
        view
        returns (uint256)
    {
        uint256 contractBalance = lexaToken.balanceOf(address(this));
        uint256 reservedBalance = totalLockedPrincipal + reservedRewardBalance;

        if (contractBalance <= reservedBalance) {
            return 0;
        }

        return contractBalance - reservedBalance;
    }

    /**
     * @notice Get tokens sent directly to the contract outside staking/reward funding flows.
     * @return Amount of unaccounted LEXA that owner may withdraw as excess
     */
    function getUnaccountedTokenBalance()
        public
        view
        returns (uint256)
    {
        uint256 contractBalance = lexaToken.balanceOf(address(this));
        uint256 accountedBalance = totalLockedPrincipal + reservedRewardBalance + rewardPoolBalance;

        if (contractBalance <= accountedBalance) {
            return 0;
        }

        return contractBalance - accountedBalance;
    }

    /**
     * @notice Get total locked amount in contract
     * @return Total locked user funds
     */
    function getTotalLockedAmount() 
        external 
        view 
        returns (uint256) 
    {
        return totalLockedPrincipal;
    }
}

contracts/SwapFeeCollector.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SwapFeeCollector
 * @dev Collects 0.3% fees from all swap output amounts
 * @notice This contract receives tokens as fees and tracks accumulated balances per token
 */
contract SwapFeeCollector is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ==================== STATE VARIABLES ====================

    /// @notice Fee percentage in basis points (0.3% = 30 basis points)
    /// @dev Using basis points: 10000 = 100%, 30 = 0.3%
    uint256 public constant FEE_PERCENTAGE = 30; // 0.3%
    uint256 public constant BASIS_POINTS = 10000; // 100% in basis points

    /// @notice Track total fees collected per token
    mapping(address token => uint256) public totalFeesCollected;

    /// @notice Track available fees to withdraw per token
    mapping(address token => uint256) public availableFees;

    /// @notice Track accumulated fees per token per collector address
    mapping(address token => mapping(address collector => uint256)) public collectorFees;

    /// @notice List of tokens that have had fees collected
    address[] public tokens;

    /// @notice Mapping to check if token already exists in tokens array
    mapping(address => bool) private tokenExists;

    /// @notice Admin address that can initiate withdrawals
    mapping(address => bool) public isAdmin;

    // ==================== EVENTS ====================

    event FeeCollected(
        address indexed token,
        address indexed collector,
        uint256 outputAmount,
        uint256 feeAmount,
        uint256 timestamp
    );

    event FeeWithdrawn(
        address indexed token,
        address indexed recipient,
        uint256 amount,
        uint256 timestamp
    );

    event AdminAdded(address indexed admin, uint256 timestamp);

    event AdminRemoved(address indexed admin, uint256 timestamp);

    event TokenListed(address indexed token, uint256 timestamp);

    // ==================== MODIFIERS ====================

    modifier onlyAdmin() {
        require(isAdmin[msg.sender] || msg.sender == owner(), "Not authorized");
        _;
    }

    // ==================== CONSTRUCTOR ====================

    constructor() Ownable(msg.sender) {
        isAdmin[msg.sender] = true;
    }

    // ==================== CORE FUNCTIONS ====================

    /**
     * @notice Collect 0.3% fee from swap output amount
     * @dev This function records fees that were already transferred to this contract
     * @param _token Address of the output token
     * @param _outputAmount Total output amount from swap (before fee deduction)
     * @param _collector Address performing the swap
     * @return feeAmount The 0.3% fee collected
     */
    function collectFee(
        address _token,
        uint256 _outputAmount,
        address _collector
    )
        external
        onlyOwner
        nonReentrant
        returns (uint256 feeAmount)
    {
        require(_token != address(0), "Invalid token address");
        require(_outputAmount > 0, "Output amount must be greater than zero");
        require(_collector != address(0), "Invalid collector address");

        // Calculate 0.3% fee
        feeAmount = (_outputAmount * FEE_PERCENTAGE) / BASIS_POINTS;
        require(feeAmount > 0, "Fee amount too small");

        // Verify that tokens were already transferred to this contract
        // (The swap handler is responsible for sending the 0.3% to this contract)
        
        // Update tracking
        totalFeesCollected[_token] += feeAmount;
        availableFees[_token] += feeAmount;
        collectorFees[_token][_collector] += feeAmount;

        // Add token to list if new
        if (!tokenExists[_token]) {
            tokens.push(_token);
            tokenExists[_token] = true;
            emit TokenListed(_token, block.timestamp);
        }

        emit FeeCollected(_token, _collector, _outputAmount, feeAmount, block.timestamp);

        return feeAmount;
    }

    /**
     * @notice Record fee that was already deducted from output
     * @dev Use this if the fee is already deducted and sent to this contract
     * @param _token Address of the fee token
     * @param _feeAmount Amount of fee received
     * @param _collector Address of the swap initiator
     */
    function recordFee(
        address _token,
        uint256 _feeAmount,
        address _collector
    )
        external
        onlyOwner
        nonReentrant
    {
        require(_token != address(0), "Invalid token address");
        require(_feeAmount > 0, "Fee amount must be greater than zero");
        require(_collector != address(0), "Invalid collector address");

        // Update tracking
        totalFeesCollected[_token] += _feeAmount;
        availableFees[_token] += _feeAmount;
        collectorFees[_token][_collector] += _feeAmount;

        // Add token to list if new
        if (!tokenExists[_token]) {
            tokens.push(_token);
            tokenExists[_token] = true;
            emit TokenListed(_token, block.timestamp);
        }

        emit FeeCollected(_token, _collector, 0, _feeAmount, block.timestamp);
    }

    // ==================== WITHDRAWAL FUNCTIONS ====================

    /**
     * @notice Withdraw collected fees for a specific token
     * @param _token Address of the token to withdraw
     * @param _amount Amount to withdraw
     */
    function withdrawFees(address _token, uint256 _amount)
        external
        onlyAdmin
        nonReentrant
    {
        require(_token != address(0), "Invalid token address");
        require(_amount > 0, "Amount must be greater than zero");
        require(availableFees[_token] >= _amount, "Insufficient fees collected");

        // Update available fees
        availableFees[_token] -= _amount;

        // Transfer tokens (using SafeERC20 for safety)
        IERC20(_token).safeTransfer(owner(), _amount);

        emit FeeWithdrawn(_token, owner(), _amount, block.timestamp);
    }

    /**
     * @notice Withdraw all collected fees for a specific token
     * @param _token Address of the token to withdraw
     */
    function withdrawAllFees(address _token)
        external
        onlyAdmin
        nonReentrant
        returns (uint256 amount)
    {
        require(_token != address(0), "Invalid token address");
        amount = availableFees[_token];
        require(amount > 0, "No fees to withdraw");

        // Update available fees
        availableFees[_token] = 0;

        // Transfer tokens
        IERC20(_token).safeTransfer(owner(), amount);

        emit FeeWithdrawn(_token, owner(), amount, block.timestamp);

        return amount;
    }

    /**
     * @notice Emergency withdrawal of a specific ERC20 token
     * @dev Only owner can call this
     * @param _token Address of the token
     * @param _amount Amount to withdraw
     */
    function emergencyWithdraw(address _token, uint256 _amount)
        external
        onlyOwner
        nonReentrant
    {
        require(_token != address(0), "Invalid token address");
        require(_amount > 0, "Amount must be greater than zero");

        uint256 balance = IERC20(_token).balanceOf(address(this));
        require(balance >= _amount, "Insufficient balance in contract");

        IERC20(_token).safeTransfer(owner(), _amount);

        emit FeeWithdrawn(_token, owner(), _amount, block.timestamp);
    }

    // ==================== ADMIN FUNCTIONS ====================

    /**
     * @notice Add an admin address that can withdraw fees
     * @param _admin Address to add as admin
     */
    function addAdmin(address _admin) external onlyOwner {
        require(_admin != address(0), "Invalid admin address");
        require(!isAdmin[_admin], "Already admin");

        isAdmin[_admin] = true;
        emit AdminAdded(_admin, block.timestamp);
    }

    /**
     * @notice Remove an admin address
     * @param _admin Address to remove from admin
     */
    function removeAdmin(address _admin) external onlyOwner {
        require(_admin != address(0), "Invalid admin address");
        require(isAdmin[_admin], "Not an admin");

        isAdmin[_admin] = false;
        emit AdminRemoved(_admin, block.timestamp);
    }

    // ==================== VIEW FUNCTIONS ====================

    /**
     * @notice Get number of unique tokens with collected fees
     */
    function getTokenCount() external view returns (uint256) {
        return tokens.length;
    }

    /**
     * @notice Get fee collected by a specific collector for a token
     * @param _token Token address
     * @param _collector Collector address
     */
    function getCollectorFees(address _token, address _collector)
        external
        view
        returns (uint256)
    {
        return collectorFees[_token][_collector];
    }

    /**
     * @notice Get available balance for a token
     * @param _token Token address
     */
    function getAvailableFees(address _token) external view returns (uint256) {
        return availableFees[_token];
    }

    /**
     * @notice Get all tokens with collected fees
     */
    function getAllTokens() external view returns (address[] memory) {
        return tokens;
    }

    /**
     * @notice Get contract balance of a specific token
     * @param _token Token address
     */
    function getTokenBalance(address _token) external view returns (uint256) {
        return IERC20(_token).balanceOf(address(this));
    }

    /**
     * @notice Check if address is admin
     * @param _address Address to check
     */
    function checkIsAdmin(address _address) external view returns (bool) {
        return isAdmin[_address];
    }
}

contracts/SwapReferralRewards.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SwapReferralRewards
 * @dev Simple contract for sending 2% BNB rewards to swap referrers
 * @notice Receives BNB and sends rewards directly to referrers
 */
contract SwapReferralRewards is Ownable, ReentrancyGuard {
    
    // ==================== STATE VARIABLES ====================
    
    /// @dev Track total distributed
    uint256 public totalDistributed;
    
    /// @dev Track per-referrer totals
    mapping(address referrer => uint256) public totalEarned;
    
    // ==================== EVENTS ====================
    
    event BNBReceived(
        address indexed sender,
        uint256 amount,
        uint256 timestamp
    );
    
    event RewardSent(
        address indexed referrer,
        address indexed swapper,
        uint256 amount,
        string txHash,
        uint256 timestamp
    );
    
    event AdminWithdrawal(
        address indexed admin,
        uint256 amount,
        uint256 timestamp
    );
    
    // ==================== CONSTRUCTOR ====================
    
    constructor() Ownable(msg.sender) {}
    
    // ==================== RECEIVE FUNCTION ====================
    
    /**
     * @notice Receive BNB for referral rewards
     */
    receive() external payable {
        emit BNBReceived(msg.sender, msg.value, block.timestamp);
    }
    
    // ==================== REWARD FUNCTION ====================
    
    /**
     * @notice Send 2% reward to referrer directly
     * @param _referrer Address to receive the reward
     * @param _swapper Address of the user who performed the swap
     * @param _amount Amount of BNB to send (2% of swap input)
     * @param _txHash Original swap transaction hash
     */
    function sendReward(
        address _referrer,
        address _swapper,
        uint256 _amount,
        string memory _txHash
    ) 
        external 
        onlyOwner 
        nonReentrant
    {
        require(_referrer != address(0), "Invalid referrer address");
        require(_swapper != address(0), "Invalid swapper address");
        require(_amount > 0, "Amount must be greater than zero");
        require(_referrer != _swapper, "Referrer cannot be swapper");
        require(address(this).balance >= _amount, "Insufficient balance");
        
        // Update tracking
        totalDistributed += _amount;
        totalEarned[_referrer] += _amount;
        
        // Send BNB
        (bool success, ) = payable(_referrer).call{value: _amount}("");
        require(success, "Transfer failed");
        
        emit RewardSent(_referrer, _swapper, _amount, _txHash, block.timestamp);
    }
    
    // ==================== ADMIN FUNCTIONS ====================
    
    /**
     * @notice Withdraw BNB from contract
     * @param _amount Amount to withdraw
     */
    function withdraw(uint256 _amount) 
        external 
        onlyOwner 
        nonReentrant
    {
        require(_amount > 0, "Amount must be greater than zero");
        require(address(this).balance >= _amount, "Insufficient balance");
        
        (bool success, ) = payable(owner()).call{value: _amount}("");
        require(success, "Withdrawal failed");
        
        emit AdminWithdrawal(owner(), _amount, block.timestamp);
    }
    
    /**
     * @notice Withdraw all BNB from contract
     */
    function withdrawAll() 
        external 
        onlyOwner 
        nonReentrant
    {
        uint256 balance = address(this).balance;
        require(balance > 0, "No balance to withdraw");
        
        (bool success, ) = payable(owner()).call{value: balance}("");
        require(success, "Withdrawal failed");
        
        emit AdminWithdrawal(owner(), balance, block.timestamp);
    }
    
    // ==================== VIEW FUNCTIONS ====================
    
    /**
     * @notice Get contract balance
     */
    function getBalance() 
        external 
        view 
        returns (uint256) 
    {
        return address(this).balance;
    }
    
    /**
     * @notice Get total earned by referrer
     */
    function getReferrerEarnings(address _referrer) 
        external 
        view 
        returns (uint256) 
    {
        return totalEarned[_referrer];
    }
    
    /**
     * @notice Get contract statistics
     */
    function getStats() 
        external 
        view 
        returns (
            uint256 balance,
            uint256 totalDistributedAmount,
            address contractOwner
        ) 
    {
        return (
            address(this).balance,
            totalDistributed,
            owner()
        );
    }
}

